"use client"

// From chatcn, chat, voice and agent UI for shadcn: https://chatcn.dev

import * as React from "react"
import { forwardRef, createElement, type SVGAttributes, type ForwardRefExoticComponent, type RefAttributes } from "react"
import { cn } from "@/lib/utils"
import { Dialog as DialogPrimitive } from "@base-ui/react/dialog"

/** chatcn theme variables and utilities this file uses, light and dark. */
const CHATCN_CSS = ":root{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-alpha-300:oklch(0 0 0 / 0.08);--chatcn-alpha-500:oklch(0 0 0 / 0.14);--chatcn-alpha-600:oklch(0 0 0 / 0.2);--chatcn-border:var(--chatcn-gray-400);--chatcn-ease-out:cubic-bezier(0.23, 1, 0.32, 1);--chatcn-ease-standard:ease;--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-fill-hover:var(--chatcn-gray-200);--chatcn-gray-100:oklch(0.970 0 0);--chatcn-gray-1000:oklch(0.145 0 0);--chatcn-gray-200:oklch(0.950 0 0);--chatcn-gray-400:oklch(0.910 0 0);--chatcn-gray-700:oklch(0.700 0 0);--chatcn-gray-800:oklch(0.525 0 0);--chatcn-gray-900:oklch(0.440 0 0);--chatcn-radius-md:8px;--chatcn-radius-xl:16px;--chatcn-radius-xs:4px;--chatcn-scrim:oklch(0 0 0 / 0.32);--chatcn-scrollbar:var(--chatcn-alpha-500);--chatcn-scrollbar-hover:var(--chatcn-alpha-600);--chatcn-shadow-xl:0 0 0 1px oklch(0 0 0 / 0.06), 0 8px 16px -4px oklch(0 0 0 / 0.08), 0 32px 64px -12px oklch(0 0 0 / 0.18);--chatcn-surface:oklch(1 0 0)}.dark{--chatcn-accent:var(--chatcn-gray-1000);--chatcn-alpha-300:oklch(1 0 0 / 0.09);--chatcn-alpha-500:oklch(1 0 0 / 0.16);--chatcn-alpha-600:oklch(1 0 0 / 0.24);--chatcn-border:var(--chatcn-gray-400);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill:var(--chatcn-gray-100);--chatcn-fill-hover:var(--chatcn-gray-200);--chatcn-gray-100:oklch(0.195 0 0);--chatcn-gray-1000:oklch(0.970 0 0);--chatcn-gray-200:oklch(0.225 0 0);--chatcn-gray-400:oklch(0.285 0 0);--chatcn-gray-700:oklch(0.500 0 0);--chatcn-gray-800:oklch(0.620 0 0);--chatcn-gray-900:oklch(0.720 0 0);--chatcn-scrim:oklch(0 0 0 / 0.6);--chatcn-scrollbar:var(--chatcn-alpha-500);--chatcn-scrollbar-hover:var(--chatcn-alpha-600);--chatcn-shadow-xl:0 0 0 1px oklch(1 0 0 / 0.1), inset 0 1px 0 oklch(1 0 0 / 0.05), 0 32px 64px -12px oklch(0 0 0 / 0.7);--chatcn-surface:oklch(0.205 0 0)}.chatcn-focus{}.chatcn-focus:focus-visible{outline: 2px solid var(--chatcn-accent); outline-offset: 2px;}.chatcn-spin{animation: chatcn-spin 0.8s linear infinite;}.chatcn-scroll{scrollbar-width: thin; scrollbar-color: var(--chatcn-scrollbar) transparent;}.chatcn-scroll:hover{scrollbar-color: var(--chatcn-scrollbar-hover) transparent;}.chatcn-scroll::-webkit-scrollbar{width: 10px; height: 10px;}.chatcn-scroll::-webkit-scrollbar-track, .chatcn-scroll::-webkit-scrollbar-corner{background: transparent;}.chatcn-scroll::-webkit-scrollbar-thumb{background-color: var(--chatcn-scrollbar); background-clip: content-box; border: 3px solid transparent; border-radius: 9999px;}.chatcn-scroll::-webkit-scrollbar-thumb:hover{background-color: var(--chatcn-scrollbar-hover);}@keyframes chatcn-spin { to { transform: rotate(360deg); } }"
if (typeof document !== "undefined" && !document.getElementById("chatcn-command-palette")) {
  const style = document.createElement("style")
  style.id = "chatcn-command-palette"
  style.textContent = CHATCN_CSS
  document.head.appendChild(style)
}

/* -------------------------------------------------------------------------------------------------
 * CommandPaletteTrigger
 * -----------------------------------------------------------------------------------------------*/

export interface CommandPaletteTriggerProps extends React.ComponentProps<"button"> {
  /** Shown as a hint after the label. Default `mod+k`. Pass `null` to hide it. */
  hotkey?: string | null
  apple?: boolean
}

function noopSubscribe() {
  return () => {}
}

/** True on macOS, iOS and iPadOS, where `mod` means Cmd. */
function isApplePlatform() {
  if (typeof navigator === "undefined") return false
  const platform =
    (navigator as Navigator & { userAgentData?: { platform?: string } }).userAgentData?.platform ??
    navigator.platform ??
    ""
  return /mac|iphone|ipad|ipod/i.test(platform)
}

/** Client-side platform check that renders the same on the server and the first client pass. */
function useApplePlatform() {
  return React.useSyncExternalStore(noopSubscribe, isApplePlatform, () => true)
}

interface ParsedHotkey {
  key: string
  mod: boolean
  meta: boolean
  ctrl: boolean
  shift: boolean
  alt: boolean
}

const KEY_ALIASES: Record<string, string> = {
  esc: "escape",
  return: "enter",
  space: " ",
  up: "arrowup",
  down: "arrowdown",
  left: "arrowleft",
  right: "arrowright",
  del: "delete",
  plus: "+",
  // "," separates alternative combos, so the comma key is spelled out: `mod+comma`.
  comma: ",",
}

function parseHotkey(combo: string): ParsedHotkey {
  // A trailing "+" is the plus key itself, so `mod++` is Cmd and plus.
  const parts = combo.trim().toLowerCase().replace(/\+\+$/, "+plus").split("+")
  const parsed: ParsedHotkey = {
    key: "",
    mod: false,
    meta: false,
    ctrl: false,
    shift: false,
    alt: false,
  }
  for (const raw of parts) {
    const part = raw.trim()
    if (part === "mod") parsed.mod = true
    else if (part === "meta" || part === "cmd" || part === "command") parsed.meta = true
    else if (part === "ctrl" || part === "control") parsed.ctrl = true
    else if (part === "shift") parsed.shift = true
    else if (part === "alt" || part === "option") parsed.alt = true
    else parsed.key = KEY_ALIASES[part] ?? part
  }
  return parsed
}

/** The `aria-keyshortcuts` value for a combo, covering both platforms for `mod`. */
function hotkeyAria(combo: string) {
  return combo
    .split(",")
    .flatMap((single) => {
      const p = parseHotkey(single)
      const tail = [
        p.alt ? "Alt" : "",
        p.shift ? "Shift" : "",
        p.key.length === 1 ? p.key.toUpperCase() : p.key[0]?.toUpperCase() + p.key.slice(1),
      ].filter(Boolean)
      if (p.mod) return [["Meta", ...tail].join("+"), ["Control", ...tail].join("+")]
      return [[p.meta ? "Meta" : "", p.ctrl ? "Control" : "", ...tail].filter(Boolean).join("+")]
    })
    .join(" ")
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

export type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
export type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
export function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

const iconNode: IconNode = [
  ["path", {"d":"M4 10.75a6.75 6.75 0 1 0 13.5 0 6.75 6.75 0 1 0-13.5 0"}],
  ["path", {"d":"m15.75 15.75 4.5 4.5"}],
]

export const SearchIcon: Icon = /* @__PURE__ */ createIcon("search", iconNode)

const SYMBOLS_APPLE: Record<string, string> = {
  mod: "⌘",
  ctrl: "⌃",
  shift: "⇧",
  alt: "⌥",
}

const NAMES_OTHER: Record<string, string> = {
  meta: "Win",
  ctrl: "Ctrl",
  shift: "Shift",
  alt: "Alt",
}

const KEY_LABELS: Record<string, string> = {
  enter: "↵",
  escape: "Esc",
  arrowup: "↑",
  arrowdown: "↓",
  arrowleft: "←",
  arrowright: "→",
  backspace: "⌫",
  delete: "Del",
  tab: "Tab",
  " ": "Space",
  space: "Space",
  pageup: "Page Up",
  pagedown: "Page Down",
  home: "Home",
  end: "End",
  insert: "Ins",
  capslock: "Caps Lock",
}

/**
 * The keys of a combo as display labels, one per `Kbd`: `["⌘", "K"]` on a Mac and
 * `["Ctrl", "K"]` elsewhere. Pass `apple` to render one platform on the server.
 */
function hotkeyKeys(combo: string, apple = isApplePlatform()): string[] {
  const parsed = parseHotkey(combo.split(",")[0] ?? combo)
  const out: string[] = []
  if (apple) {
    // Apple order: Control, Option, Shift, Command.
    if (parsed.ctrl) out.push(SYMBOLS_APPLE.ctrl as string)
    if (parsed.alt) out.push(SYMBOLS_APPLE.alt as string)
    if (parsed.shift) out.push(SYMBOLS_APPLE.shift as string)
    if (parsed.mod || parsed.meta) out.push(SYMBOLS_APPLE.mod as string)
  } else {
    // Everywhere else: Ctrl, Win, Alt, Shift.
    if (parsed.ctrl || parsed.mod) out.push(NAMES_OTHER.ctrl as string)
    if (parsed.meta) out.push(NAMES_OTHER.meta as string)
    if (parsed.alt) out.push(NAMES_OTHER.alt as string)
    if (parsed.shift) out.push(NAMES_OTHER.shift as string)
  }
  const key = parsed.key
  out.push(
    KEY_LABELS[key] ??
      (key.length === 1 ? key.toUpperCase() : key[0]?.toUpperCase() + key.slice(1)),
  )
  return out
}

function Kbd({ className, ...props }: React.ComponentProps<"kbd">) {
  return (
    <kbd
      data-slot="kbd"
      className={cn(
        "rounded-(--chatcn-radius-xs) bg-(color:--chatcn-fill) text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) inline-flex h-5 min-w-5 items-center justify-center px-1 font-sans tabular-nums shadow-[inset_0_-1px_0_var(--chatcn-alpha-300)]",
        className,
      )}
      {...props}
    />
  )
}

/** Platform-aware keys for one hotkey string, as a row of `Kbd`s. */
function HotkeyKbds({
  combo,
  apple,
  className,
}: {
  combo: string
  apple: boolean
  className?: string
}) {
  return (
    <span aria-hidden="true" className={cn("flex shrink-0 items-center gap-0.5", className)}>
      {hotkeyKeys(combo, apple).map((key, i) => (
        <Kbd key={i}>{key}</Kbd>
      ))}
    </span>
  )
}

/**
 * A quiet search-field-shaped button that opens the palette: "Search…" and the shortcut. Pass
 * `onClick={() => setOpen(true)}`; a pointer open fades in, a keyboard open is instant.
 */
export function CommandPaletteTrigger({
  hotkey = "mod+k",
  apple: appleProp,
  className,
  children = "Search…",
  ...props
}: CommandPaletteTriggerProps) {
  const detectedApple = useApplePlatform()
  const apple = appleProp ?? detectedApple
  return (
    <button
      type="button"
      data-slot="command-palette-trigger"
      aria-keyshortcuts={hotkey ? hotkeyAria(hotkey) : undefined}
      className={cn(
        "chatcn-focus rounded-(--chatcn-radius-md) bg-(color:--chatcn-fill) text-(color:--chatcn-fg-subtle) text-[0.875rem]/[1.25rem] tracking-[-0.003em] flex h-8 w-full min-w-0 items-center gap-2 ps-2.5 pe-1.5 text-start",
        "ease-(--chatcn-ease-standard) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg-muted) transition-[background-color,color] duration-150",
        "pointer-coarse:h-11",
        className,
      )}
      {...props}
    >
      <SearchIcon aria-hidden="true" className="size-4 shrink-0" />
      <span className="min-w-0 flex-1 truncate">{children}</span>
      {hotkey ? (
        <HotkeyKbds combo={hotkey} apple={apple} className="pointer-coarse:hidden" />
      ) : null}
    </button>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export interface CommandPaletteItem {
  id: string
  /** The searchable, emphasized text. */
  label: string
  /** Group id. Items without one go in an unlabeled group at the top. */
  group?: string
  /** 16 px icon before the label. */
  icon?: React.ReactNode
  /** A hotkey string such as `mod+shift+o`, rendered as platform-aware keys. */
  shortcut?: string
  /** Muted text at the end of the row, for example a date or "Model". */
  hint?: React.ReactNode
  /** Extra words that match without being shown: synonyms, ids, file names. */
  keywords?: string
  disabled?: boolean
  /** Keep the palette open after selecting, for toggles. */
  keepOpen?: boolean
  onSelect?: () => void
}

export interface CommandPaletteGroup {
  id: string
  /** Sentence case: "Chats", "Actions", "Models". */
  label: string
  /** Rows shown while the query is empty. Searching shows every match. */
  emptyLimit?: number
  /** Only show this group once the user types. */
  searchOnly?: boolean
}

export interface CommandPaletteProps {
  items: CommandPaletteItem[]
  /** Group order and labels. Groups not listed follow in order of appearance. */
  groups?: CommandPaletteGroup[]
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** The query. Controlled with `onQueryChange`, for example to fetch chats from a server. */
  query?: string
  defaultQuery?: string
  onQueryChange?: (query: string) => void
  /** Rank and filter `items` by the query. Turn off when the server already filtered them. */
  filter?: boolean
  /** Shows a spinner in the field after 200 ms, and "Searching…" while there are no rows. */
  loading?: boolean
  /** Toggles the palette from anywhere. Default `mod+k`. Pass `null` to bind nothing. */
  hotkey?: string | null
  /** Called after an item's own `onSelect`. */
  onSelect?: (item: CommandPaletteItem) => void
  placeholder?: string
  /** Accessible name of the dialog. Default "Command palette". */
  label?: string
  /** Under "No results for …". */
  emptyHint?: React.ReactNode
  /** Replaces the key hints at the bottom. Pass `false` to hide them. */
  footer?: React.ReactNode | false
  /** Force Mac or PC key labels, for screenshots. Detected by default. */
  apple?: boolean
  /** Portal container. Defaults to `document.body`. */
  container?: DialogPrimitive.Portal.Props["container"]
  className?: string
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

function useControllable<T>(prop: T | undefined, initial: T, onChange?: (value: T) => void) {
  const [state, setState] = React.useState(initial)
  const value = prop !== undefined ? prop : state
  const set = React.useCallback(
    (next: T) => {
      if (prop === undefined) setState(next)
      onChange?.(next)
    },
    [prop, onChange],
  )
  return [value, set] as const
}

let tracking = false

/* -------------------------------------------------------------------------------------------------
 * Motion
 *
 * The palette is opened dozens of times a day, mostly from the keyboard, so it follows Raycast:
 * opened or closed with a key, it appears and leaves instantly. Opened with a pointer, it fades
 * in over 150 ms (opacity only, no scale) and out over 110 ms. The list height follows the
 * results over 150 ms so the panel never jumps; reduced motion snaps it.
 * -----------------------------------------------------------------------------------------------*/

type Modality = "keyboard" | "pointer"

let lastModality: Modality = "keyboard"

/** Remembers whether the last interaction was a key or a pointer, for open and close motion. */
function trackModality() {
  if (tracking || typeof document === "undefined") return
  tracking = true
  document.addEventListener("keydown", () => (lastModality = "keyboard"), true)
  document.addEventListener("pointerdown", () => (lastModality = "pointer"), true)
}

/* -------------------------------------------------------------------------------------------------
 * Hotkey strings
 *
 * A hotkey is a `+` separated combo, case insensitive: `mod+k`, `mod+shift+o`, `mod+/`, `shift+?`,
 * `escape`, `/`. `mod` is Cmd on Apple platforms and Ctrl everywhere else, so one binding works on
 * every keyboard. Several combos can share a handler: `"mod+k, mod+p"`.
 * -----------------------------------------------------------------------------------------------*/

type HotkeyHandler = (event: KeyboardEvent) => void

interface HotkeyOptions {
  /** Skip the binding without unbinding it. */
  enabled?: boolean
  /**
   * Fire while focus is in a text field. Defaults to true for combos with Cmd, Ctrl or Alt and
   * false for bare keys, so typing `/` in the composer never steals focus.
   */
  allowInInput?: boolean
  /** Call `preventDefault` when the combo fires. Default true. */
  preventDefault?: boolean
}

type HotkeyMap = Record<string, HotkeyHandler | ({ handler: HotkeyHandler } & HotkeyOptions)>

/* -------------------------------------------------------------------------------------------------
 * useChatcnHotkeys
 * -----------------------------------------------------------------------------------------------*/

interface UseChatcnHotkeysOptions {
  /** Turn every binding off at once, for example while a dialog owns the keyboard. */
  enabled?: boolean
  /** Listen on this element instead of the window. */
  target?: React.RefObject<HTMLElement | null>
}

/** Shifted symbols arrive as their own key on US layouts (`?` for Shift+/), so accept both. */
const SHIFTED: Record<string, string> = { "?": "/", "<": ",", ">": ".", ":": ";", "{": "[" }

function matchesHotkey(event: KeyboardEvent, hotkey: ParsedHotkey, apple = isApplePlatform()) {
  const wantMeta = hotkey.meta || (hotkey.mod && apple)
  const wantCtrl = hotkey.ctrl || (hotkey.mod && !apple)
  if (event.metaKey !== wantMeta || event.ctrlKey !== wantCtrl || event.altKey !== hotkey.alt)
    return false
  const key = event.key?.toLowerCase() ?? ""
  // Shift is implied by symbols like `?`, so only check it for letters, digits and named keys.
  const symbol = key.length === 1 && !/[a-z0-9]/.test(key)
  if (!symbol && event.shiftKey !== hotkey.shift) return false
  if (key === hotkey.key) return true
  if (SHIFTED[key] === hotkey.key && hotkey.shift) return true
  // Alt and Option remap letters on macOS (Option+K is "˚"), so fall back to the physical key.
  const code = event.code?.toLowerCase() ?? ""
  return code === `key${hotkey.key}` || code === `digit${hotkey.key}`
}

function isEditable(target: EventTarget | null) {
  const el = target as HTMLElement | null
  if (!el || typeof el.closest !== "function") return false
  if (el.isContentEditable) return true
  const tag = el.tagName
  if (tag === "TEXTAREA" || tag === "SELECT") return true
  if (tag !== "INPUT") return false
  const type = (el as HTMLInputElement).type
  return !["button", "checkbox", "radio", "range", "submit", "reset", "color", "file"].includes(
    type,
  )
}

/**
 * Global keyboard shortcuts for app chrome. Handlers can change on every render without
 * re-binding. Never fires during IME composition, on auto-repeat for toggles, or for bare keys
 * while the user types in a field.
 *
 *   useChatcnHotkeys({
 *     "mod+k": () => setPaletteOpen((o) => !o),
 *     "mod+shift+o": newChat,
 *     "mod+/": () => setShortcutsOpen(true),
 *   })
 */
function useChatcnHotkeys(
  map: HotkeyMap,
  { enabled = true, target }: UseChatcnHotkeysOptions = {},
) {
  const mapRef = React.useRef(map)
  mapRef.current = map
  const signature = Object.keys(map).join("|")

  React.useEffect(() => {
    if (!enabled) return
    const bindings = signature
      .split("|")
      .filter(Boolean)
      .map((combo) => ({ combo, parsed: combo.split(",").map(parseHotkey) }))
    const apple = isApplePlatform()
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.isComposing || event.keyCode === 229 || event.defaultPrevented) return
      for (const { combo, parsed } of bindings) {
        const entry = mapRef.current[combo]
        if (!entry) continue
        const { handler, ...options } = typeof entry === "function" ? { handler: entry } : entry
        if (options.enabled === false) continue
        const hit = parsed.find((p) => matchesHotkey(event, p, apple))
        if (!hit) continue
        const modified = hit.mod || hit.meta || hit.ctrl || hit.alt
        const allowInInput = options.allowInInput ?? modified
        if (!allowInInput && isEditable(event.target)) continue
        if (event.repeat && modified) {
          event.preventDefault()
          return
        }
        if (options.preventDefault !== false) event.preventDefault()
        handler(event)
        return
      }
    }
    const node: HTMLElement | Window = target?.current ?? window
    node.addEventListener("keydown", onKeyDown as EventListener)
    return () => node.removeEventListener("keydown", onKeyDown as EventListener)
  }, [enabled, signature, target])
}

/* -------------------------------------------------------------------------------------------------
 * Matching
 *
 * Two matchers share one result shape, a score and the ranges to emphasize:
 * - `fuzzyMatch` for short labels (command palette, thread titles): the query letters in order,
 *   rewarded for word starts and runs, so "nwc" finds "New chat" and "rspg" finds "Runs page".
 * - `findTerms` for full text (chat search): every word of the query as a substring, so the
 *   snippet shows exactly what matched.
 * -----------------------------------------------------------------------------------------------*/

/** Half-open `[start, end)` character ranges into the searched text. */
type MatchRange = readonly [start: number, end: number]

/* -------------------------------------------------------------------------------------------------
 * useChatcnShellFuzzy
 * -----------------------------------------------------------------------------------------------*/

interface FuzzyItem<T> {
  item: T
  score: number
  /** Ranges in the label, for emphasis. */
  ranges: MatchRange[]
}

interface FuzzyResult {
  /** Higher is better. Comparable between items for the same query only. */
  score: number
  ranges: MatchRange[]
}

/** Lowercase and strip accents so "resume" finds "Résumé", only when lengths (and ranges) hold. */
function fold(text: string) {
  const lower = text.toLowerCase()
  const stripped = lower.normalize("NFD").replace(/\p{M}/gu, "")
  return stripped.length === lower.length ? stripped : lower
}

const WORD_BREAK = /[\s\-_/.:,()[\]]/

function mergeRanges(ranges: MatchRange[]): MatchRange[] {
  const sorted = [...ranges].sort((a, b) => a[0] - b[0])
  const out: [number, number][] = []
  for (const [s, e] of sorted) {
    const last = out[out.length - 1]
    if (last && s <= last[1]) last[1] = Math.max(last[1], e)
    else out.push([s, e])
  }
  return out
}

/**
 * Subsequence match for labels. Returns null when the query letters do not all appear in order.
 * Contiguous substrings and word-start hits rank first.
 */
function fuzzyMatch(query: string, text: string): FuzzyResult | null {
  const q = fold(query.trim())
  if (!q) return { score: 0, ranges: [] }
  const t = fold(text)

  // A direct substring is the strongest signal; prefer one that starts a word.
  let best = -1
  for (let i = t.indexOf(q); i !== -1; i = t.indexOf(q, i + 1)) {
    if (best === -1) best = i
    if (i === 0 || WORD_BREAK.test(t[i - 1] ?? "")) {
      best = i
      break
    }
  }
  if (best !== -1) {
    const atStart = best === 0 || WORD_BREAK.test(t[best - 1] ?? "")
    return {
      score: 1000 + (atStart ? 200 : 0) - best - (t.length - q.length) * 0.5,
      ranges: [[best, best + q.length]],
    }
  }

  // Multi-word queries: every word as a substring, in any order ("page runs").
  const words = q.split(/\s+/).filter(Boolean)
  if (words.length > 1) {
    const ranges: MatchRange[] = []
    for (const word of words) {
      const at = t.indexOf(word)
      if (at === -1) {
        ranges.length = 0
        break
      }
      ranges.push([at, at + word.length])
    }
    if (ranges.length)
      return { score: 600 - (t.length - q.length) * 0.5, ranges: mergeRanges(ranges) }
  }

  // Subsequence, greedy but preferring word starts.
  const needle = q.replace(/\s+/g, "")
  const ranges: [number, number][] = []
  let score = 0
  let ti = 0
  let prev = -2
  for (const ch of needle) {
    // Continuing a run beats jumping ahead; otherwise look for this letter at a word start
    // before settling for the next occurrence.
    let found = prev === ti - 1 && t[ti] === ch ? ti : -1
    for (let j = ti; found !== ti && j < t.length; j++) {
      if (t[j] !== ch) continue
      if (found === -1) found = j
      if (j === 0 || WORD_BREAK.test(t[j - 1] ?? "")) {
        found = j
        break
      }
    }
    if (found === -1) return null
    const wordStart = found === 0 || WORD_BREAK.test(t[found - 1] ?? "")
    score += wordStart ? 12 : 1
    if (found === prev + 1) {
      score += 6
      const last = ranges[ranges.length - 1]
      if (last) last[1] = found + 1
    } else {
      score -= Math.min(found - ti, 8) * 0.5
      ranges.push([found, found + 1])
    }
    prev = found
    ti = found + 1
  }
  // Letters scattered through the middle of words read as noise ("rate" in "Compare Bun and
  // Node for the"). Allow one stray letter; acronyms like "nwc" for "New chat" still match.
  const strays = ranges.filter(
    ([start, end]) => end - start === 1 && start > 0 && !WORD_BREAK.test(t[start - 1] ?? ""),
  ).length
  if (strays > 1) return null
  return { score: score - t.length * 0.05, ranges }
}

/**
 * Filters and ranks `items` by a fuzzy match on `getLabel` (plus `getKeywords`, which match but
 * are never highlighted). With an empty query, every item comes back in its original order.
 */
function useChatcnShellFuzzy<T>(
  items: readonly T[],
  query: string,
  getLabel: (item: T) => string,
  getKeywords?: (item: T) => string | undefined,
): FuzzyItem<T>[] {
  const labelRef = React.useRef(getLabel)
  labelRef.current = getLabel
  const keywordsRef = React.useRef(getKeywords)
  keywordsRef.current = getKeywords
  return React.useMemo(() => {
    const q = query.trim()
    if (!q) return items.map((item) => ({ item, score: 0, ranges: [] }))
    const out: (FuzzyItem<T> & { index: number })[] = []
    items.forEach((item, index) => {
      const label = labelRef.current(item)
      const hit = fuzzyMatch(q, label)
      const keywords = keywordsRef.current?.(item)
      const extra = !hit && keywords ? fuzzyMatch(q, keywords) : null
      if (hit) out.push({ item, score: hit.score, ranges: hit.ranges, index })
      else if (extra) out.push({ item, score: extra.score * 0.6, ranges: [], index })
    })
    return out
      .sort((a, b) => b.score - a.score || a.index - b.index)
      .map(({ index: _index, ...rest }) => rest)
  }, [items, query])
}

interface RankedItem {
  item: CommandPaletteItem
  ranges: MatchRange[]
  score: number
}

interface RenderedGroup {
  id: string
  label?: string
  rows: RankedItem[]
}

/** True only after `active` has held for `delay` ms, so fast results never flash a spinner. */
function useDelayed(active: boolean, delay = 200) {
  const [shown, setShown] = React.useState(false)
  React.useEffect(() => {
    if (!active) {
      setShown(false)
      return
    }
    const id = window.setTimeout(() => setShown(true), delay)
    return () => window.clearTimeout(id)
  }, [active, delay])
  return shown
}

/** The kit's one spinner. 0.8 s per turn, slowed to 1.2 s under reduced motion. */
function Spinner({ className, label }: { className?: string; label?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      data-slot="spinner"
      className={cn("chatcn-spin size-3.5 shrink-0", className)}
    >
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeOpacity="0.2" strokeWidth="1.5" />
      <path
        d="M8 1.75A6.25 6.25 0 0 1 14.25 8"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
      />
    </svg>
  )
}

/** Splits text into plain and matched segments, for rendering `<mark>` around the matches. */
function splitByRanges(text: string, ranges: readonly MatchRange[]) {
  const out: { text: string; match: boolean }[] = []
  let at = 0
  for (const [s, e] of ranges) {
    if (s > at) out.push({ text: text.slice(at, s), match: false })
    if (e > s) out.push({ text: text.slice(s, e), match: true })
    at = Math.max(at, e)
  }
  if (at < text.length) out.push({ text: text.slice(at), match: false })
  return out
}

function Emphasis({ text, ranges }: { text: string; ranges: readonly MatchRange[] }) {
  if (!ranges.length) return <>{text}</>
  return (
    <>
      {splitByRanges(text, ranges).map((segment, i) =>
        segment.match ? (
          <mark key={i} className="text-(color:--chatcn-fg) bg-transparent font-medium">
            {segment.text}
          </mark>
        ) : (
          <span key={i} className="text-(color:--chatcn-fg-muted)">
            {segment.text}
          </span>
        ),
      )}
    </>
  )
}

/* -------------------------------------------------------------------------------------------------
 * CommandPalette
 * -----------------------------------------------------------------------------------------------*/

/**
 * Cmd/Ctrl+K: one field that finds chats, runs actions and switches models. Fuzzy matching with
 * the matched letters emphasized, groups with labels, shortcut hints, and full keyboard control:
 * arrows (or Ctrl+N and Ctrl+P) move, Home and End jump, Enter runs, Escape closes.
 */
export function CommandPalette({
  items,
  groups = [],
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  query: queryProp,
  defaultQuery = "",
  onQueryChange,
  filter = true,
  loading = false,
  hotkey = "mod+k",
  onSelect,
  placeholder = "Search chats, actions and models…",
  label = "Command palette",
  emptyHint = "Try fewer letters, or a word from the chat title.",
  footer,
  apple: appleProp,
  container,
  className,
}: CommandPaletteProps) {
  const detectedApple = useApplePlatform()
  const apple = appleProp ?? detectedApple
  const [open, setOpenState] = useControllable(openProp, defaultOpen, onOpenChange)
  const [query, setQuery] = useControllable(queryProp, defaultQuery, onQueryChange)
  const [cursorState, setCursorState] = React.useState({ query: defaultQuery, index: -1 })
  const inputRef = React.useRef<HTMLInputElement>(null)
  const listRef = React.useRef<HTMLDivElement>(null)
  const contentRef = React.useRef<HTMLDivElement>(null)
  const baseId = React.useId()
  const listboxId = `${baseId}-listbox`

  React.useEffect(trackModality, [])

  // Decide the motion for this open or close at the moment it flips. Starts instant, so a palette
  // that renders open never fades in.
  const [instant, setInstant] = React.useState(true)
  const [prevOpen, setPrevOpen] = React.useState(open)
  if (prevOpen !== open) {
    setPrevOpen(open)
    setInstant(lastModality === "keyboard")
  }

  const setOpen = React.useCallback(
    (next: boolean) => {
      setOpenState(next)
      if (next) {
        // A fresh palette every time: empty query, first row active.
        if (queryProp === undefined) setQuery("")
        setCursorState({ query: "", index: -1 })
      }
    },
    [setOpenState, setQuery, queryProp],
  )

  const openRef = React.useRef(open)
  openRef.current = open
  useChatcnHotkeys(
    hotkey
      ? {
          [hotkey]: () => {
            lastModality = "keyboard"
            setOpen(!openRef.current)
          },
        }
      : {},
  )

  /* Ranking --------------------------------------------------------------------------------*/

  const searching = query.trim().length > 0
  const ranked = useChatcnShellFuzzy(
    items,
    filter ? query : "",
    (item) => item.label,
    (item) => item.keywords,
  )

  const rendered = React.useMemo<RenderedGroup[]>(() => {
    const meta = new Map(groups.map((g, i) => [g.id, { ...g, order: i }]))
    const buckets = new Map<string, RenderedGroup & { best: number; order: number }>()
    const appearance: string[] = []
    for (const r of ranked) {
      const key = r.item.group ?? ""
      let bucket = buckets.get(key)
      if (!bucket) {
        const g = meta.get(key)
        if (!searching && g?.searchOnly) continue
        if (!appearance.includes(key)) appearance.push(key)
        bucket = {
          id: key,
          label: g?.label ?? (key || undefined),
          rows: [],
          best: r.score,
          order: g ? g.order : groups.length + appearance.indexOf(key),
        }
        buckets.set(key, bucket)
      }
      const limit = meta.get(key)?.emptyLimit
      if (!searching && limit !== undefined && bucket.rows.length >= limit) continue
      bucket.rows.push(r)
    }
    const list = [...buckets.values()].filter((b) => b.rows.length > 0)
    // Ungrouped first; while searching, the group with the best match leads.
    list.sort((a, b) => {
      if (a.id === "" || b.id === "") return a.id === "" ? -1 : 1
      return searching && filter ? b.best - a.best || a.order - b.order : a.order - b.order
    })
    return list
  }, [ranked, groups, searching, filter])

  const flat = React.useMemo(() => rendered.flatMap((g) => g.rows), [rendered])
  const enabledIndexes = React.useMemo(
    () => flat.map((r, i) => (r.item.disabled ? -1 : i)).filter((i) => i !== -1),
    [flat],
  )

  // The cursor belongs to the query it was set for: a new query always starts at the top match.
  const cursor = cursorState.query === query ? cursorState.index : -1
  const active =
    cursor !== -1 && flat[cursor] && !flat[cursor]?.item.disabled
      ? cursor
      : (enabledIndexes[0] ?? -1)
  const setActiveIndex = (index: number) => setCursorState({ query, index })
  const optionId = (i: number) => `${baseId}-option-${i}`

  /* List height ---------------------------------------------------------------------------*/

  const [height, setHeight] = React.useState<number>()
  const [measured, setMeasured] = React.useState(false)
  React.useLayoutEffect(() => {
    if (!open) {
      setMeasured(false)
      setHeight(undefined)
      return
    }
    const node = contentRef.current
    if (!node) return
    const update = () => setHeight(node.offsetHeight)
    update()
    // Enable the height transition only after the first measurement, so opening never grows.
    const frame = requestAnimationFrame(() => setMeasured(true))
    const observer = new ResizeObserver(update)
    observer.observe(node)
    return () => {
      cancelAnimationFrame(frame)
      observer.disconnect()
    }
  }, [open])

  /* Selection -----------------------------------------------------------------------------*/

  const select = (index: number) => {
    const row = flat[index]
    if (!row || row.item.disabled) return
    row.item.onSelect?.()
    onSelect?.(row.item)
    if (!row.item.keepOpen) {
      lastModality = "keyboard"
      setOpen(false)
    }
  }

  const move = (to: number) => {
    if (!enabledIndexes.length) return
    setActiveIndex(to)
    const el = document.getElementById(optionId(to))
    // Instant: arrow-key movement never animates, and the scroll is never smooth.
    el?.scrollIntoView({ block: "nearest" })
  }

  const step = (dir: 1 | -1) => {
    if (!enabledIndexes.length) return
    const at = enabledIndexes.indexOf(active)
    const next =
      at === -1
        ? enabledIndexes[0]
        : enabledIndexes[(at + dir + enabledIndexes.length) % enabledIndexes.length]
    if (next !== undefined) move(next)
  }

  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return
    const ctrlOnly = event.ctrlKey && !event.metaKey && !event.altKey
    if (event.key === "ArrowDown" || (ctrlOnly && event.key === "n")) {
      event.preventDefault()
      step(1)
    } else if (event.key === "ArrowUp" || (ctrlOnly && event.key === "p")) {
      event.preventDefault()
      step(-1)
    } else if (event.key === "Home" && !event.shiftKey) {
      event.preventDefault()
      const first = enabledIndexes[0]
      if (first !== undefined) move(first)
    } else if (event.key === "End" && !event.shiftKey) {
      event.preventDefault()
      const last = enabledIndexes[enabledIndexes.length - 1]
      if (last !== undefined) move(last)
    } else if (event.key === "Enter") {
      event.preventDefault()
      if (active !== -1) select(active)
    }
  }

  // Hover moves the highlight only when the pointer itself moves, never when the list scrolls
  // under a still pointer during keyboard navigation.
  const pointer = React.useRef<{ x: number; y: number } | null>(null)
  const onPointerMove = (event: React.PointerEvent, index: number) => {
    const last = pointer.current
    pointer.current = { x: event.clientX, y: event.clientY }
    if (last && last.x === event.clientX && last.y === event.clientY) return
    if (index !== active && !flat[index]?.item.disabled) setActiveIndex(index)
  }

  /* Status --------------------------------------------------------------------------------*/

  const showSpinner = useDelayed(loading)
  const resultsLabel = searching
    ? loading && !flat.length
      ? ""
      : flat.length === 0
        ? `No results for ${query.trim()}`
        : `${flat.length} ${flat.length === 1 ? "result" : "results"}`
    : ""
  const [announcement, setAnnouncement] = React.useState("")
  React.useEffect(() => {
    const id = window.setTimeout(() => setAnnouncement(resultsLabel), 400)
    return () => window.clearTimeout(id)
  }, [resultsLabel])

  let index = -1

  return (
    <DialogPrimitive.Root
      open={open}
      // The document listeners already saw the key or pointer that caused this change.
      onOpenChange={(next) => setOpen(next)}
    >
      <DialogPrimitive.Portal container={container}>
        <DialogPrimitive.Backdrop
          data-slot="command-palette-backdrop"
          data-palette-instant={instant ? "" : undefined}
          className={cn(
            "bg-(color:--chatcn-scrim) fixed inset-0 z-50",
            "ease-(--chatcn-ease-out) transition-opacity duration-150",
            "data-[ending-style]:opacity-0 data-[ending-style]:duration-110 data-[starting-style]:opacity-0",
            "data-[palette-instant]:transition-none",
          )}
        />
        <DialogPrimitive.Popup
          data-slot="command-palette"
          data-palette-instant={instant ? "" : undefined}
          aria-label={label}
          initialFocus={inputRef}
          className={cn(
            "bg-(color:--chatcn-surface) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xl) rounded-(--chatcn-radius-xl) fixed top-[12dvh] left-1/2 z-50 -translate-x-1/2",
            "flex max-h-[calc(100dvh-14dvh-1rem)] w-[min(40rem,calc(100vw-2rem))] flex-col overflow-hidden outline-none",
            "ease-(--chatcn-ease-out) transition-opacity duration-150",
            "data-[ending-style]:opacity-0 data-[ending-style]:duration-110 data-[starting-style]:opacity-0",
            "data-[palette-instant]:transition-none",
            "forced-colors:outline-1 forced-colors:outline-solid",
            className,
          )}
        >
          <DialogPrimitive.Title className="sr-only">{label}</DialogPrimitive.Title>

          <div className="flex h-13 shrink-0 items-center gap-3 px-4 pointer-coarse:h-14">
            <SearchIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-4.5 shrink-0" />
            <input
              ref={inputRef}
              role="combobox"
              aria-expanded="true"
              aria-controls={listboxId}
              aria-autocomplete="list"
              aria-activedescendant={active !== -1 ? optionId(active) : undefined}
              aria-label={placeholder.replace(/…$/, "")}
              autoComplete="off"
              autoCorrect="off"
              spellCheck={false}
              data-slot="command-palette-input"
              value={query}
              placeholder={placeholder}
              onChange={(event) => setQuery(event.target.value)}
              onKeyDown={onKeyDown}
              className={cn(
                "text-[0.9375rem]/[1.5rem] tracking-[-0.006em] text-(color:--chatcn-fg) placeholder:text-(color:--chatcn-fg-subtle) h-full min-w-0 flex-1 bg-transparent outline-none",
                "pointer-coarse:text-[1rem]/[1.5rem] pointer-coarse:tracking-[-0.01em]",
              )}
            />
            {showSpinner ? (
              <Spinner label="Searching" className="text-(color:--chatcn-fg-subtle) size-4" />
            ) : null}
          </div>

          <div
            ref={listRef}
            data-slot="command-palette-list"
            data-measured={measured ? "" : undefined}
            className={cn(
              "border-(color:--chatcn-border) chatcn-scroll min-h-0 overflow-y-auto overscroll-contain border-t",
              "chatcn-scroll max-h-[min(25rem,60dvh)]",
              "data-[measured]:ease-(--chatcn-ease-out) data-[measured]:transition-[height] data-[measured]:duration-150 motion-reduce:transition-none",
            )}
            style={height !== undefined ? { height } : undefined}
          >
            <div ref={contentRef}>
              <div
                id={listboxId}
                role="listbox"
                aria-label="Results"
                className={cn("flex flex-col p-2", flat.length === 0 && "hidden")}
              >
                {rendered.map((group) => {
                  const labelId = `${baseId}-group-${group.id || "top"}`
                  return (
                    // biome-ignore lint/a11y/useSemanticElements: option groups inside a listbox
                    <div
                      key={group.id || "top"}
                      role="group"
                      aria-labelledby={group.label ? labelId : undefined}
                      className="flex flex-col not-first:mt-2"
                    >
                      {group.label ? (
                        <div
                          id={labelId}
                          className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex h-8 items-center px-2 font-medium select-none"
                        >
                          {group.label}
                        </div>
                      ) : null}
                      {group.rows.map((row) => {
                        index++
                        const i = index
                        const isActive = i === active
                        const { item } = row
                        return (
                          // biome-ignore lint/a11y/useKeyWithClickEvents lint/a11y/useFocusableInteractive: focus stays on the combobox, which handles the keys (aria-activedescendant)
                          <div
                            key={item.id}
                            id={optionId(i)}
                            role="option"
                            aria-selected={isActive}
                            aria-disabled={item.disabled || undefined}
                            aria-keyshortcuts={
                              item.shortcut ? hotkeyAria(item.shortcut) : undefined
                            }
                            data-slot="command-palette-item"
                            data-active={isActive ? "" : undefined}
                            onPointerMove={(event) => onPointerMove(event, i)}
                            onPointerDown={(event) => event.preventDefault()}
                            onClick={() => select(i)}
                            className={cn(
                              "rounded-(--chatcn-radius-md) flex h-10 cursor-default items-center gap-3 px-2 select-none",
                              "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg)",
                              "data-[active]:bg-(color:--chatcn-fill-hover)",
                              "aria-disabled:opacity-50",
                              "[&_svg]:size-4 [&_svg]:shrink-0",
                              "pointer-coarse:min-h-11",
                            )}
                          >
                            {item.icon ? (
                              <span
                                aria-hidden="true"
                                className={cn(
                                  "text-(color:--chatcn-fg-subtle) grid size-4 shrink-0 place-items-center",
                                  isActive && "text-(color:--chatcn-fg)",
                                )}
                              >
                                {item.icon}
                              </span>
                            ) : null}
                            <span className="min-w-0 flex-1 truncate">
                              <Emphasis
                                text={item.label}
                                ranges={
                                  !searching
                                    ? []
                                    : filter
                                      ? row.ranges
                                      : // Pre-filtered items still show what matched.
                                        (fuzzyMatch(query.trim(), item.label)?.ranges ?? [])
                                }
                              />
                            </span>
                            {item.hint ? (
                              <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
                                {item.hint}
                              </span>
                            ) : null}
                            {item.shortcut ? (
                              <HotkeyKbds combo={item.shortcut} apple={apple} />
                            ) : null}
                          </div>
                        )
                      })}
                    </div>
                  )
                })}
              </div>

              {flat.length === 0 ? (
                <div
                  data-slot="command-palette-empty"
                  className="flex flex-col items-center gap-1 px-6 py-10 text-center"
                >
                  {loading ? (
                    <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg-muted)">Searching…</p>
                  ) : searching ? (
                    <>
                      <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) text-balance">
                        No results for “{query.trim()}”
                      </p>
                      {emptyHint ? (
                        <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) text-pretty">
                          {emptyHint}
                        </p>
                      ) : null}
                    </>
                  ) : (
                    <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg-muted)">Type to search.</p>
                  )}
                </div>
              ) : null}
            </div>
          </div>

          {footer === false ? null : (
            <div
              data-slot="command-palette-footer"
              className="border-(color:--chatcn-border) text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex h-10 shrink-0 items-center gap-4 border-t px-4 pointer-coarse:hidden"
            >
              {footer ?? (
                <>
                  <span className="flex items-center gap-1.5">
                    <span aria-hidden="true" className="flex gap-0.5">
                      <Kbd>↑</Kbd>
                      <Kbd>↓</Kbd>
                    </span>
                    Navigate
                  </span>
                  <span className="flex items-center gap-1.5">
                    <Kbd aria-hidden="true">↵</Kbd>
                    Open
                  </span>
                  <span className="ms-auto flex items-center gap-1.5">
                    <Kbd aria-hidden="true">Esc</Kbd>
                    Close
                  </span>
                </>
              )}
            </div>
          )}

          <span aria-live="polite" className="sr-only">
            {announcement}
          </span>
        </DialogPrimitive.Popup>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}

export default CommandPalette

