/**
 * The palette open in an AI chat app: it starts on recent chats, actions and models, then
 * searches type in and the ranked results narrow, from a chat about checkout to the theme switch
 * and the models. Loops. Type or pick a result and the tour waits for you.
 */
export default function CommandPalettePreview() {
  const [step, setStep] = React.useState({ query: 1, typed: 3 })
  const [held, hold] = useHold()
  const [mine, setMine] = React.useState("")
  const [container, setContainer] = React.useState<HTMLDivElement | null>(null)

  React.useEffect(() => {
    if (reducedMotion() || held) return
    const full = QUERIES[step.query]!
    const done = step.typed >= full.length
    const id = window.setTimeout(
      () =>
        setStep((s) =>
          done ? { query: (s.query + 1) % QUERIES.length, typed: 0 } : { query: s.query, typed: s.typed + 1 },
        ),
      done ? REST_MS : TYPE_MS,
    )
    return () => window.clearTimeout(id)
  }, [step, held])

  const query = held ? mine : QUERIES[step.query]!.slice(0, step.typed)

  return (
    <FitFrame minWidth="40rem">
      <div className="flex w-full flex-col items-center justify-center gap-4 p-6">
        <div ref={setContainer} className="relative h-[20.5rem] w-full max-w-xl [transform:translateZ(0)] [&_[data-slot=command-palette-backdrop]]:hidden">
          {container ? (
            <CommandPalette
              items={ITEMS}
              groups={groups}
              open
              onOpenChange={() => hold()}
              query={query}
              onQueryChange={(q) => {
                hold()
                setMine(q)
              }}
              onSelect={() => hold()}
              hotkey={null}
              apple
              container={container}
              // The preview is scaled, so the screen based offsets would not fit it.
              className="top-0 max-h-[20.5rem] w-full"
            />
          ) : null}
        </div>
        <MoreOn slug="command-palette">Chats, actions and models in one ranked search. On</MoreOn>
      </div>
    </FitFrame>
  )
}
